 21	fn fixtureValue(g: *d.Graph, name: []const u8) !d.Value {
 22	    var kind: ?d.TypedArrayKind = null;
 23	    var suffix: ?[]const u8 = null;
 24	    for (kinds) |k| {
 25	        const tag = @tagName(k);
 26	        if (std.mem.startsWith(u8, name, tag) and name.len > tag.len and name[tag.len] == '_') {
 27	            kind = k;
 28	            suffix = name[tag.len + 1 ..];
 29	            break;
 30	        }
 31	    }
 32	    if (std.mem.startsWith(u8, name, "DataView_")) suffix = name[9..];
 33	    if (suffix) |shape| {
 34	        const width = if (kind) |k| k.bytesPerElement() else 1;
 35	        if (std.mem.eql(u8, shape, "empty_buffer")) return makeView(g, kind, try g.arrayBuffer(""), 0, 0);
 36	        const b = try sequence(g, if (std.mem.eql(u8, shape, "odd_explicit")) 33 else 32);
 37	        if (std.mem.eql(u8, shape, "full")) return makeView(g, kind, b, 0, 32 / width);
 38	        if (std.mem.eql(u8, shape, "sub")) return makeView(g, kind, b, width, 2);
 39	        if (std.mem.eql(u8, shape, "empty_end")) return makeView(g, kind, b, 32, 0);
 40	        if (std.mem.eql(u8, shape, "odd_explicit")) return makeView(g, kind, b, 0, 1);
 41	        if (std.mem.eql(u8, shape, "identity")) {
 42	            const v = try makeView(g, kind, b, width, 2);
