 70	        return root;
 71	    }
 72	    if (std.mem.eql(u8, name, "float64_negative_zero") or std.mem.eql(u8, name, "raw_float_bits")) {
 73	        const bytes: []const u8 = if (std.mem.eql(u8, name, "raw_float_bits"))
 74	            &.{ 1, 0, 0, 0, 0, 0, 248, 127, 0, 0, 0, 0, 0, 0, 0, 128 }
