test: test-zig
    #!/usr/bin/env bash
    set -euo pipefail
    for m in {{modules}}; do (cd "$m" && go test ./...); done

lint: lint-zig
    #!/usr/bin/env bash
    set -euo pipefail
    for m in {{modules}}; do
        (cd "$m" && go mod tidy && modernize -fix ./... && go vet ./... && staticcheck ./... && govulncheck ./... && golangci-lint run ./...)
